        double pi = 0;
        int iterations = 1000000; // Number of iterations for better accuracy

        for (int i = 0; i < iterations; i++)
        {
            pi += Math.Pow(-1, i) / (2 * i + 1);
        }

        pi *= 4; // Multiply by 4 to get the value of pi

        // Round pi to 5 decimal places
