client.once('ready', () => {
  console.log(`Logged in as ${client.user.tag}`);
});

client.on('interactionCreate', async (interaction) => {
  if (!interaction.isChatInputCommand()) return;

  const { commandName } = interaction;

  if (commandName === 'play') {
    // Get the voice channel where the user is connected
    const member = interaction.member;
    const channel = member.voice.channel;

    if (!channel) {
      await interaction.reply('You must be in a voice channel to use this command.');
      return;
    }

    // Join the voice channel
    const connection = joinVoiceChannel({
      channelId: channel.id,
      guildId: channel.guild.id,
      adapterCreator: channel.guild.voiceAdapterCreator,
    });

    // Create an audio player
    const player = createAudioPlayer();

    // Load the audio resource
    const resource = createAudioResource('./path/to/your/audio/file.mp3'); // Replace with your actual file path

    // Play the audio
    player.play(resource);

    // Connect the player to the connection
    connection.subscribe(player);

    // Handle end event
    player.on(AudioPlayerStatus.Idle, () => {
      console.log('Playback finished');
      connection.destroy();
    });

    await interaction.reply('Playing audio...');
  }
});

// Login to Discord with your app's token
