layout(location = 0) in vec2 aPos;

void main()
{
    gl_Position = vec4(aPos, 0.0, 1.0);
}
```

### Fragment Shader

The fragment shader will perform the actual raycasting logic. It will cast rays from the center of the screen to all points on the edges of the screen and determine if they intersect with any obstacles.

```glsl
#version 330 core

out vec4 FragColor;

uniform sampler2D uWorldTexture; // Texture containing the world data
uniform float uCellSize;         // Size of each cell in the world texture

// Function to check if a point is inside an obstacle
bool isObstacle(vec2 pos)
{
    return texture(uWorldTexture, pos / uCellSize).r > 0.5;
}

void main()
{
    vec2 uv = gl_FragCoord.xy / vec2(800, 600); // Assuming a 800x600 window

    // Cast rays from the center of the screen to the edges
    for (int i = -1; i <= 1; ++i)
    {
        for (int j = -1; j <= 1; ++j)
        {
            if (i == 0 && j == 0) continue; // Skip the center

            vec2 direction = normalize(vec2(i, j));
            vec2 origin = vec2(0.5, 0.5); // Center of the screen

            float t = 0.0;
            while (true)
            {
                vec2 point = origin + t * direction;
                if (isObstacle(point))
                {
                    break;
                }
                t += 0.01; // Step size
            }

            // Draw a line from the origin to the intersection point
            FragColor = vec4(direction, 0.0, 1.0);
        }
    }
}
```

### Explanation

- **Vertex Shader**: The vertex shader simply passes through the position of each vertex.
- **Fragment Shader**:
  - `uWorldTexture`: A texture that contains the world data, where each pixel represents a cell in the world. If the value is greater than 0.5, it's considered an obstacle.
  - `uCellSize`: The size of each cell in the world texture.
  - `isObstacle`: A function that checks if a given point is inside an obstacle by sampling the world texture.
  - The main loop casts rays from the center of the screen to the edges and determines if they intersect with any obstacles. If an intersection is found, it draws a line from the origin to the intersection point.

