function parseCSV(csvText) {
  const lines = csvText.split('\n');
  const headers = lines[0].split(',');

  const data = [];

  for (let i = 1; i < lines.length; i++) {
    const values = lines[i].split(',');
    const obj = {};

    for (let j = 0; j < headers.length; j++) {
      obj[headers[j]] = values[j];
    }

    data.push(obj);
  }

  return data;
}

