### 2. Extracting Text from an HTML Document (using html2canvas)
First, include the html2canvas library in your project:

```html
<script src="https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js"></script>
```

Then, create a function to extract text from an HTML element:

```javascript
function extractTextFromHTML(elementId) {
    return new Promise((resolve, reject) => {
        html2canvas(document.getElementById(elementId)).then(canvas => {
            const imgData = canvas.toDataURL('image/png');
            const img = new Image();
            img.src = imgData;

            img.onload = () => {
                const ctx = canvas.getContext('2d');
                const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
                const pixels = imageData.data;

                // Simple OCR-like text extraction (basic example)
                let text = '';
                for (let y = 0; y < canvas.height; y++) {
                    for (let x = 0; x < canvas.width; x++) {
                        const index = (y * canvas.width + x) * 4;
                        if (pixels[index] > 128 && pixels[index + 1] > 128 && pixels[index + 2] > 128) {
                            text += ' ';
                        } else {
                            text += '*'; // Placeholder for non-white pixels
                        }
                    }
                }
                resolve(text);
            };
        });
    });
}

// Example usage:
extractTextFromHTML('yourElementId').then(text => {
    console.log(text);
});
```

### Notes:
- **PDF.js** is more reliable for extracting text from PDFs.
- **html2canvas** is useful for extracting text from HTML elements but requires additional processing (like OCR) to convert pixel data into readable text.
- For more advanced text extraction, consider using OCR libraries like **Tesseract.js**.

