import java.nio.ByteOrder

class Reverb(private val decayFactor: Float) {

    private external fun initReverb(reverbPtr: Long)
    private external fun applyReverb(input: Float, reverbPtr: Long): Float

    companion object {
        init {
            System.loadLibrary("reverb") // Load the shared library
        }

        @JvmStatic
        private external fun createReverb(): Long
    }

    private var reverbPtr: Long = 0L

    init {
