Sure, I can help you with that! Here's an example of how you could write a Connect-4 game in Python:

```python
import numpy as np

# Define the size of the board
ROWS = 6
COLS = 7

# Initialize the board
board = np.zeros((ROWS, COLS))

def print_board(board):
    # Print the current state of the board
    for row in range(ROWS):
        print("|", end="")
        for col in range(COLS):
            if board[row][col] == 0:
                print(" ", end="|")
            elif board[row][col] == 1:
                print("X", end="|")
            else:
                print("O", end="|")
        print()

def is_valid_location(board, col):
    # Check if a column is valid (not full)
    return board[ROWS - 1][col] == 0

def get_next_open_row(board, col):
    # Get the next open row in a column
    for r in range(ROWS):
        if board[r][col] == 0:
            return r

def drop_piece(board, row, col, piece):
    # Drop a piece into the board at the specified location
    board[row][col] = piece

def winning_move(board, piece):
    # Check for a winning move horizontally, vertically, or diagonally
    # Horizontal
    for c in range(COLS - 3):
        for r in range(ROWS):
            if board[r][c] == piece and board[r][c + 1] == piece and board[r][c + 2] == piece and board[r][c + 3] == piece:
                return True

    # Vertical
    for c in range(COLS):
        for r in range(ROWS - 3):
            if board[r][c] == piece and board[r + 1][c] == piece and board[r + 2][c] == piece and board[r + 3][c] == piece:
                return True

    # Diagonal (positive slope)
    for c in range(COLS - 3):
        for r in range(ROWS - 3):
            if board[r][c] == piece and board[r + 1][c + 1] == piece and board[r + 2][c + 2] == piece and board[r + 3][c + 3] == piece:
                return True

    # Diagonal (negative slope)
    for c in range(COLS - 3):
        for r in range(3, ROWS):
            if board[r][c] == piece and board[r - 1][c + 1] == piece and board[r - 2][c + 2] == piece and board[r - 3][c + 3] == piece:
                return True

    return False

def main():
    turn = 0
    game_over = False

    while not game_over:
        # Player 1's turn
        if turn % 2 == 0:
            col = int(input("Player 1, make your selection (0-6): "))
            if is_valid_location(board, col):
                row = get_next_open_row(board, col)
                drop_piece(board, row, col, 1)
                if winning_move(board, 1):
                    print("Player 1 wins!")
                    game_over = True
        else:
            # Player 2's turn
            col = int(input("Player 2, make your selection (0-6): "))
            if is_valid_location(board, col):
                row = get_next_open_row(board, col)
                drop_piece(board, row, col, 2)
                if winning_move(board, 2):
                    print("Player 2 wins!")
                    game_over = True

        print_board(board)
        turn += 1

if __name__ == "__main__":
    main()
```

This code defines a simple Connect-4 game where two players take turns dropping their pieces into columns on a 6x7 grid. The `print_board` function displays the current state of the board, `is_valid_location` checks if a column is available for a new piece, `get_next_open_row` finds the lowest empty spot in a given column, `drop_piece` places a piece on the board, and `winning_move` determines if there is a winner.

The `main` function handles the game loop, alternating between player 1 and player 2 until someone wins or all spaces are filled. You can run this script in any Python environment to play the game.

